import type { PluginOptions } from "@opencode-ai/plugin"

export type ImageConfig = {
  apiKey?: string
  baseUrl: string
  model: string
  size: string
  quality: string
  outputDir: string
}

const DEFAULTS = {
  baseUrl: "https://api.openai.com/v1",
  model: "gpt-image-1",
  size: "1024x1024",
  quality: "auto",
  outputDir: "images",
}

export function resolveConfig(
  options: PluginOptions,
  env: Record<string, string | undefined> = process.env,
): ImageConfig {
  return {
    apiKey: (options.apiKey as string | undefined) ?? env.OPENAI_API_KEY ?? env.OPENAI_KEY,
    baseUrl: (options.baseUrl as string | undefined) ?? env.OPENAI_BASE_URL ?? DEFAULTS.baseUrl,
    model: (options.model as string | undefined) ?? env.OPENAI_IMAGE_MODEL ?? DEFAULTS.model,
    size: (options.size as string | undefined) ?? DEFAULTS.size,
    quality: (options.quality as string | undefined) ?? DEFAULTS.quality,
    outputDir: (options.outputDir as string | undefined) ?? DEFAULTS.outputDir,
  }
}
