```ts
import { mkdir, writeFile } from "node:fs/promises"
import path from "node:path"
import type { ImageConfig } from "./config"

export type GenerateImageArgs = {
  prompt: string
  size?: string
  quality?: string
  outputDir?: string
}

export type GeneratedImage = {
  filePath: string
  filename: string
  mime: string
}

export async function generateImage(
  config: ImageConfig,
  args: GenerateImageArgs,
  cwd: string,
  signal?: AbortSignal,
): Promise<GeneratedImage> {
  if (!config.apiKey) {
    throw new Error("Missing API key. Set OPENAI_API_KEY (or OPENAI_KEY) or pass options.apiKey in your opencode plugin config.")
  }
  const baseUrl = config.baseUrl.replace(/\/+$/, "")
  const res = await fetch(`${baseUrl}/images/generations`, {
    method: "POST",
    signal,
    headers: {
      Authorization: `Bearer ${config.apiKey}`,
      "Content-Type": "application/json",
    },
    body: JSON.stringify({
      model: config.model,
      prompt: args.prompt,
      n: 1,
      size: args.size ?? config.size,
      quality: args.quality ?? config.quality,
      response_format: "b64_json",
    }),
  })

  if (!res.ok) {
    const body = await res.text().catch(() => "")
    throw new Error(`Image API request failed (${res.status}): ${body}`)
  }

  const json = (await res.json()) as { data?: Array<{ b64_json?: string; url?: string }> }
  const item = json.data?.[0]

  let buffer: Buffer
  let mime = "image/png"
  if (item?.b64_json) {
    buffer = Buffer.from(item.b64_json, "base64")
  } else if (item?.url) {
    const imgRes = await fetch(item.url, { signal })
    if (!imgRes.ok) throw new Error(`Failed to download image from ${item.url} (${imgRes.status})`)
    buffer = Buffer.from(await imgRes.arrayBuffer())
    mime = imgRes.headers.get("content-type") ?? "image/png"
  } else {
    throw new Error("Image API response contained no image data.")
  }

  const dir = path.resolve(cwd, args.outputDir ?? config.outputDir)
  await mkdir(dir, { recursive: true })
  const filename = filenameFor(args.prompt, mime)
  const filePath = path.join(dir, filename)
  await writeFile(filePath, buffer)
  return { filePath, filename, mime }
}

export function filenameFor(prompt: string, mime: string): string {
  const ext = mime === "image/jpeg" ? "jpg" : mime === "image/webp" ? "webp" : "png"
  const slug =
    prompt.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-+|-+$/g, "").slice(0, 48) || "image"
  const stamp = new Date().toISOString().replace(/[:.]/g, "-")
  return `${stamp}-${slug}.${ext}`
}
```

