```ts
import type { Plugin } from "@opencode-ai/plugin"
import { tool } from "@opencode-ai/plugin"
import { resolveConfig } from "./config"
import { generateImage } from "./image"

const createImagePlugin: Plugin = async (_input, options = {}) => {
  const config = resolveConfig(options)

  return {
    tool: {
      create_image: tool({
        description:
          "Generate an image using the configured OpenAI-compatible image API and save it to disk. " +
          "Use for hero images, illustrations, icons, product shots, and placeholders while building web pages or visual content. " +
          "You write the prompt yourself: describe subject, composition, style, lighting, palette, and mood in detail. " +
          "After generating, read the returned file path to inspect the image, then regenerate with refined prompts to iterate. " +
          "Keep a consistent art direction (same medium, palette, and mood) across all images for the same page.",
        args: {
          prompt: tool.schema.string().describe("Detailed description of the image to create"),
          size: tool.schema.enum(["1024x1024", "1024x1792", "1792x1024", "auto"]).optional().describe("Image dimensions"),
          quality: tool.schema.enum(["auto", "standard", "high"]).optional().describe("Quality level"),
          outputDir: tool.schema.string().optional().describe("Directory to save the image into, relative to the project directory; defaults to ./images"),
        },
        async execute(args, context) {
          const { filePath, filename, mime } = await generateImage(config, args, context.directory, context.abort)
          return {
            title: `Generated ${filename}`,
            output: `Image saved to ${filePath}`,
            attachments: [{ type: "file", mime, url: filePath, filename }],
          }
        },
      }),
    },
  }
}

export default createImagePlugin
```

